code_sketch:
func Collide(a, b Shape) string {
    switch x := a.(type) {
    case Circle:
        switch y := b.(type) {
        case Square:
            return fmt.Sprintf("circle %v vs square %v", x.Radius, y.Side)
        case Circle:
            return "two circles"
        }
    }
    panic(fmt.Sprintf("unhandled pair %T/%T", a, b))
}

