type Visitor interface {
    VisitCircle(Circle)
    VisitSquare(Square)
}
type Shape interface{ Accept(Visitor) }
func (c Circle) Accept(v Visitor) { v.VisitCircle(c) }

// second axis: one visitor struct per first-operand type
type CircleVsVisitor struct{ lhs Circle }
func (v CircleVsVisitor) VisitSquare(s Square) { /* circle x square */ }
